import math
from fractions import Fraction

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def euler_phi(n):
    if n == 1:
        return 1
    factors = prime_factorization(n)
    result = n
    for p in factors:
        result -= result // p
    return result

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def order(a, n):
    """Calculates the multiplicative order of a modulo n."""
    if gcd(a, n) != 1:
        # This should not happen based on the problem setup (3 not dividing m)
        raise ValueError(f"{a} is not coprime to {n}")

    phi_n = euler_phi(n)

    # Find all divisors of phi_n
    divisors = get_divisors(phi_n)
    divisors.sort()

    for k in divisors:
        if pow(a, k, n) == 1:
            return k

    # Fallback, should not be reached if phi_n is correct
    return phi_n

