import math

def phi(n):
    """Calculates Euler's totient function phi(n)."""
    if n == 0:
        return 0
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def order_mod(a, n):
    """Calculates the multiplicative order of a modulo n."""
