            divs.add(n // i)
    return sorted(list(divs))

def calculate_C(m):
    """Calculates the number of cycles C(m) for the permutation x -> 3x mod m."""
    C_m = 0
    divisors = get_divisors(m)

    # Sum over k|m, k>1
